      dialog = 3,
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      role1 = 449000,
      role2 = 402107,
      role3 = 402202,
      role5 = 449401,
      roleanim = 1.1,
      sentence = "无数的“祝你们幸福”此起彼伏地响起，不知从哪儿跑来几个特遣队员们，他们也高高举起灯棒——",
      next = {132}
    },
    [132] = {
      beijing = 4080,
      dialog = 2,
      idx = 5,
      music = "40_Produce_My_LOVE",
      renming = "队员",
      renwu = "npc",
      role1 = 449000,
      role2 = 402107,
      role3 = 402202,
      role5 = 449401,
      roleanim = 1.1,
      sentence = "祝白队幸福！！",
      next = {133}
    },
    [133] = {
      beijing = 4080,
      dialog = 3,
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      role1 = 449000,
      role2 = 402110,
      role3 = 402202,
      role5 = 449401,
      roleanim = 1.1,
      sentence = "凝刻爱意的火花如同一个个小小的星火。那一刻，我们像是收到了整个城市的庇佑与偏爱。",
      next = {134}
    },
    [134] = {
      beijing = 4080,
      dialog = 3,
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      role1 = 449000,
      role2 = 402110,
      role3 = 402202,
      role5 = 449401,
      roleanim = 1.1,
      sentence = "在那盛大的祝福声里，白起紧紧地抱住了我。",
      next = {135}
    },
    [135] = {
      beijing = 4080,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "40_Produce_My_LOVE",
