    }
  },
  [840121] = {
    [1] = {
      beijing = 4847,
      dhead = 110,
      dialog = 1,
      music = "1014_2023anniversary_scene",
      renming = "$u",
      renwu = "npc",
      sentence = "李泽言，总感觉你对茶桌礼仪很是熟练。",
      next = {2}
    },
    [2] = {
      beijing = 4847,
      dhead = 110,
      dialog = 1,
      music = "1014_2023anniversary_scene",
      renming = "$u",
      renwu = "npc",
      sentence = "是不是经常有人会请你去茶馆喝茶谈生意啊。",
      next = {3}
    },
    [3] = {
      beijing = 4847,
      dialog = 2,
      idx = 1,
      music = "1014_2023anniversary_scene",
      renming = "李泽言",
      renwu = "npc",
      role1 = 1167000,
      role2 = 102101,
      role3 = 102203,
      role5 = 1167402,
      ruchang = -1,
      sentence = "嗯，是有不少。为什么突然这么问？",
      next = {4}
    },
    [4] = {
      beijing = 4847,
      dhead = 113,
      dialog = 1,
      music = "1014_2023anniversary_scene",
      renming = "$u",
      renwu = "npc",
      role1 = 1167000,
      role2 = 102101,
      role3 = 102203,
      role5 = 1167402,
      sentence = "就是帮别人泡了几杯茶之后，好像能发现这个人的特点似的。",
      next = {5}
    },
    [5] = {
      beijing = 4847,
      dhead = 113,
      dialog = 1,
      music = "1014_2023anniversary_scene",
      renming = "$u",
      renwu = "npc",
      role1 = 1167000,
      role2 = 102101,
      role3 = 102203,
      role5 = 1167402,
      sentence = "有人专心致志地品茶，有人就心不在焉想打瞌睡。",
      next = {6}
    },
    [6] = {
      beijing = 4847,
      dhead = 114,
      dialog = 1,
      music = "1014_2023anniversary_scene",
      renming = "$u",
      renwu = "npc",
      role1 = 1167000,
      role2 = 102101,
      role3 = 102203,
      role5 = 1167402,
      sentence = "你坐在那就有种“成功商务人士”才有的感觉。",
      next = {7}
    },
    [7] = {
      beijing = 4847,
      dialog = 2,
      idx = 1,
      music = "1014_2023anniversary_scene",
      renming = "李泽言",
      renwu = "npc",
      role1 = 1167000,
      role2 = 102104,
      role3 = 102203,
      role5 = 1167402,
      sentence = "哪来那么多奇奇怪怪的评价。",
      next = {8}
    },
    [8] = {
      beijing = 4847,
      dialog = 2,
      idx = 1,
      music = "1014_2023anniversary_scene",
      renming = "李泽言",
      renwu = "npc",
      role1 = 1167000,
      role2 = 102104,
      role3 = 102203,
      role5 = 1167402,
      sentence = "那你有没有看出来，其实我很少和别人一起喝茶。",
      next = {9}
    },
    [9] = {
      beijing = 4847,
      dhead = 111,
      dialog = 1,
      music = "1014_2023anniversary_scene",
      renming = "$u",
      renwu = "npc",
      role1 = 1167000,
      role2 = 102104,
      role3 = 102203,
      role5 = 1167402,
      sentence = "不会错失很多生意机会吗？",
